if (!Object.hasOwn(C2S, TESTCAP_TYPE)) {
  C2S[TESTCAP_TYPE] = { round: (v) => Number.isInteger(v) && v >= 1 && v <= 99 };
  log.info(`registered intent ${TESTCAP_TYPE}`);
}
if (!Object.hasOwn(C2S, TESTENEMY_TYPE)) {
